// tb_systolic_mx.v - drives the multi-format engine with vectors generated by
// tools/gen_mx_vectors.py and checks every output row bit for bit.
//
// Settings: -DGRID_N=8 and plusarg +PRE=build/vectors/mx_N8_fp8
`timescale 1ns/1ps
`ifndef GRID_N
`define GRID_N 4
`endif
module tb_systolic_mx;
    localparam N = `GRID_N, IW = $clog2(N) + 1;
    localparam SW = 4 + 4*N*8, EW = N*48 + N*10;
    localparam MAXB = 32768, MAXR = 8192;

    reg clk = 0, rst = 1;
    reg in_valid = 0, in_last = 0;
    reg [1:0] in_fmt = 0;
    reg [N*8-1:0] a_col = 0, b_row = 0, a_sc = 0, b_sc = 0;
    wire out_valid;
    wire [IW-1:0] out_row_idx;
    wire [N*48-1:0] out_row;
    wire [N*10-1:0] out_exp;

    systolic_mx #(.N(N)) dut (.clk(clk), .rst(rst), .in_valid(in_valid),
        .in_last(in_last), .in_fmt(in_fmt), .a_col(a_col), .b_row(b_row),
        .in_a_scale(a_sc), .in_b_scale(b_sc), .out_valid(out_valid),
        .out_row_idx(out_row_idx), .out_row(out_row), .out_exp(out_exp));
    always #5 clk = ~clk;

    reg [SW-1:0] stim [0:MAXB-1];
    reg [EW-1:0] expv [0:MAXR-1];
    reg [63:0]   meta [0:3];
    reg [1023:0] pre;

    integer nb, nr, macs, vbeats, b, r_seen, errors, cyc, first_in, last_out, exp_idx;

    always @(posedge clk) cyc <= rst ? 0 : cyc + 1;

    always @(posedge clk) if (!rst && out_valid) begin
        if (r_seen >= nr) begin
            errors = errors + 1; $display("EXTRA output row");
        end else begin
            if ({out_row, out_exp} !== expv[r_seen] || out_row_idx !== (r_seen % N)) begin
                errors = errors + 1;
                if (errors < 6)
                    $display("MISMATCH output row %0d (job %0d, row %0d)", r_seen, r_seen / N, r_seen % N);
            end
            r_seen   = r_seen + 1;
            last_out = cyc;
        end
    end

    initial begin
        if (!$value$plusargs("PRE=%s", pre)) begin
            $display("need +PRE=<vector prefix>"); $finish;
        end
        $readmemh({pre, "_meta.hex"}, meta);
        nb = meta[0]; nr = meta[1]; macs = meta[2]; vbeats = meta[3];
        $readmemh({pre, "_stim.hex"}, stim, 0, nb - 1);
        $readmemh({pre, "_exp.hex"},  expv, 0, nr - 1);
        errors = 0; r_seen = 0;

        repeat (3) @(posedge clk); #1 rst = 0;
        @(posedge clk); #1;
        first_in = cyc;
        for (b = 0; b < nb; b = b + 1) begin
            {in_valid, in_last, in_fmt, a_col, b_row, a_sc, b_sc} = stim[b];
            @(posedge clk); #1;
        end
        in_valid = 0; in_last = 0;
        repeat (4*N + 10) @(posedge clk);
        #1;
        if (r_seen != nr) begin
            errors = errors + 1;
            $display("MISSING rows: saw %0d expected %0d", r_seen, nr);
        end
        $display("MX %0dx%0d %0s: %0d rows, %0d results checked, %0d errors",
                 N, N, pre, r_seen, r_seen * N, errors);
        $display("MX %0dx%0d %0s: %0d multiplies on %0d cells in %0d ticks = %0d.%02d per cell per tick",
                 N, N, pre, macs, N*N, last_out - first_in + 1,
                 (macs / (N*N)) / (last_out - first_in + 1),
                 ((100 * (macs / (N*N))) / (last_out - first_in + 1)) % 100);
        if (errors == 0) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
